RECON.check_due:
function check_due() {
		global $wpdb;
		$table = self::table_name();
		$advance = self::DUE_ADVANCE_DAYS;
		$target_date = date( 'Y-m-d', time() + $advance * 86400 );

		// Rasam aktyvius irasys kur predicted_empty_date <= today + advance
		// IR dar nefire'inome refill_due (status = 'active')
		$rows = $wpdb->get_results( $wpdb->prepare(
			"SELECT rt.*, u.user_email
			 FROM `$table` rt
			 JOIN `{$wpdb->users}` u ON u.ID = rt.user_id
			 WHERE rt.status = 'active'
			   AND rt.predicted_empty_date <= %s
			 ORDER BY rt.predicted_empty_date ASC
			 LIMIT 100",
			$target_date
		) );

		foreach ( $rows as $row ) {
			if ( ! $row->user_email || ! class_exists( 'Petshop_Event_Registry' ) ) {
				continue;
			}
			$product = wc_get_product( $row->product_id );
			$product_name = $product ? $product->get_name() : '(produktas #' . $row->product_id . ')';

			Petshop_Event_Registry::emit( 'refill_due', $row->user_email, array(
				'pet_id'               => $row->pet_id ? (int) $row->pet_id : 0,
				'product_id'           => (int) $row->product_id,
				'product_name'         => $product_name,
				'predicted_empty_date' => $row->predicted_empty_date,
				'confidence'           => (float) $row->confidence,
				'last_order_id'        => (int) $row->last_order_id,
				'days_since_last_order' => (int) round( ( time() - strtotime( $row->last_purchase_date ) ) / 86400 ),
			), array(
				'event_id' => 'refill_due_' . $row->user_id . '_' . $row->product_id . '_' . $row->predicted_empty_date,
			) );

			// --- S312: laiskas VISADA i outbox'a; sprendimas fiksuojamas ten.
			// Srauto specifines salygos tikrinamos per petshop_email_eligibility
			// filtra (zr. eligibility_filter()), kad praleidimo priezastis butu
			// matoma ataskaitose, o ne dingtu tyliame return'e.
			if ( class_exists( 'Petshop_Email_Dispatch' ) ) {
				$pet_name = '';
				if ( $row->pet_id ) {
					$pet_name = (string) $wpdb->get_var( $wpdb->prepare(
						"SELECT pet_name FROM {$wpdb->prefix}ps_pets WHERE id = %d", $row->pet_id ) );
				}
				Petshop_Email_Dispatch::enqueue(
					'refill_due',
					$row->user_email,
					array(
						'pet_name'     => $pet_name,
						'product_id'   => (int) $row->product_id,
						'product_name' => $product_name,
						'product_url'  => $product ? $product->get_permalink() : home_url( '/' ),
						'reorder_url'  => add_query_arg( 'add-to-cart', (int) $row->product_id, wc_get_cart_url() ),
						'confidence'   => (float) $row->confidence,
					),
					array(
						'job_key' => 'refill_due:' . $row->user_id . ':' . $row->product_id . ':' . $row->predicted_empty_date,
						'user_id' => (int) $row->user_id,
						// context — reikalingas eligibility filtrui
						'context' => array(
							'user_id'            => (int) $row->user_id,
							'product_id'         => (int) $row->product_id,
							'last_purchase_date' => $row->last_purchase_date,
							// S323: reikalinga kalibravimo nuorodai (feedback_url)
							'refill_id'          => (int) $row->id,
